#[cfg(test)]
mod tests {
    use super::*;

    fn test_config() -> Config {
        let mut config = Config::default();
        config.general.install_prefix = "/usr/local".to_string();
        config.sources.push(Source {
            label: "nvme-root".to_string(),
            volume: "/.btrfs-nvme".to_string(),
            subvolumes: vec![
                SubvolConfig {
                    name: "@".to_string(),
                    manual_only: false,
                    snapshot_name: None,
                },
                SubvolConfig {
                    name: "@home".to_string(),
                    manual_only: false,
                    snapshot_name: None,
                },
            ],
            device: "/dev/nvme0n1p2".to_string(),
            snapshot_dir: ".btrbk-snapshots".into(),
            target_subdirs: vec!["nvme".into()],
            target_labels: vec![],
        });
        config.targets.push(Target {
            label: "primary-22tb".to_string(),
            serial: "ZXA0LMAE".to_string(),
            serials: vec!["ZXA0LMAE".to_string()],
            mount_uuid: None,
            mount: "/mnt/backup-22tb".to_string(),
            role: TargetRole::Primary,
            retention: Retention {
                weekly: 4,
                monthly: 2,
                daily: 0,
                yearly: 0,
            },
            display_name: String::new(),
        });
        config
    }

    #[test]
    fn render_btrbk_conf_test() {
        let config = test_config();
        let result = render_btrbk_conf(&config);
        // Check volume, subvolume, target, retention, header
        assert!(result.contains("volume /.btrfs-nvme"), "missing volume");
        assert!(
            result
                .lines()
                .any(|l| l.trim().starts_with("subvolume") && l.trim().ends_with("@")),
            "missing subvolume @"
        );
        assert!(
            result
                .lines()
                .any(|l| l.trim().starts_with("subvolume") && l.contains("@home")),
            "missing subvolume @home"
        );
        assert!(
            result
                .lines()
                .any(|l| l.trim().starts_with("target") && l.contains("/mnt/backup-22tb")),
            "missing target /mnt/backup-22tb"
        );
        assert!(result.contains("4w 2m"), "missing retention 4w 2m");
        assert!(
            result.contains("# Generated by btrdasd setup"),
            "missing header"
        );
        // Verify per-source snapshot_dir is used (not hardcoded)
        assert!(
            result.contains("snapshot_dir          .btrbk-snapshots"),
            "missing default snapshot_dir"
        );
    }

    #[test]
    fn render_btrbk_conf_uses_per_source_snapshot_dir() {
        let mut config = test_config();
        // Add a second source with a different snapshot_dir
        config.sources.push(Source {
            label: "hdd-projects".to_string(),
            volume: "/.btrfs-hdd".to_string(),
            subvolumes: vec![SubvolConfig {
                name: "ClaudeCodeProjects".to_string(),
                manual_only: false,
                snapshot_name: None,
            }],
            device: "/dev/sda".to_string(),
            snapshot_dir: "ClaudeCodeProjects/.btrbk-snapshots".into(),
            target_subdirs: vec![],
            target_labels: vec![],
        });
        let result = render_btrbk_conf(&config);
        // The HDD source must use its custom snapshot_dir, not the default
        assert!(
            result.contains("snapshot_dir          ClaudeCodeProjects/.btrbk-snapshots"),
            "btrbk.conf must use per-source snapshot_dir, got:\n{result}"
        );
    }

    fn subvol(name: &str, snapshot_name: Option<&str>) -> SubvolConfig {
        SubvolConfig {
            name: name.to_string(),
            manual_only: false,
            snapshot_name: snapshot_name.map(str::to_string),
        }
    }

    fn retention(daily: u32, weekly: u32, monthly: u32, yearly: u32) -> Retention {
        Retention {
            weekly,
            monthly,
            daily,
            yearly,
        }
    }

    fn target(label: &str, mount: &str, role: TargetRole, retention: Retention) -> Target {
        Target {
            label: label.to_string(),
            serial: String::new(),
            serials: vec![],
            mount_uuid: None,
            mount: mount.to_string(),
            role,
            retention,
            display_name: String::new(),
        }
    }

    /// The shape of the author's deployment (`.claude/rules/backup.md`
    /// §Targets and Retention): one long-retention primary that receives
    /// everything, two short-retention recovery drives that receive only
    /// system data, a system source that fans out to all three, and a bulk
    /// source scoped to the primary alone.
    fn multi_target_config() -> Config {
        let targets = vec![
            target(
                "primary-22tb",
                "/mnt/backup-22tb",
                TargetRole::Primary,
                retention(7, 4, 12, 1),
            ),
            target(
                "system-recovery-A-2tb",
                "/mnt/backup-system-recovery-A",
                TargetRole::Mirror,
                retention(7, 0, 0, 0),
            ),
            target(
                "system-recovery-B-2tb",
                "/mnt/backup-system-recovery-B",
                TargetRole::Mirror,
                retention(7, 0, 0, 0),
            ),
        ];
        let sources = vec![
            Source {
                label: "nvme".to_string(),
                volume: "/.btrfs-nvme".to_string(),
                subvolumes: vec![
                    subvol("@", None),
                    subvol("@home", None),
                    subvol("@root", None),
                    subvol("@var/log", None),
                ],
                device: "/dev/nvme0n1p2".to_string(),
                snapshot_dir: ".btrbk-snapshots".to_string(),
                target_subdirs: vec!["nvme".to_string()],
                target_labels: vec![],
            },
            Source {
                label: "hdd-projects".to_string(),
                volume: "/.btrfs-hdd".to_string(),
                subvolumes: vec![
                    subvol("ClaudeCodeProjects", None),
                    subvol(
                        "ClaudeCodeProjects/DAS-Backup-Manager",
                        Some("das-backup-manager"),
                    ),
                ],
                device: "/dev/sda".to_string(),
                snapshot_dir: "ClaudeCodeProjects/.btrbk-snapshots".to_string(),
                target_subdirs: vec![],
                target_labels: vec!["primary-22tb".to_string()],
            },
            Source {
                label: "retired".to_string(),
                volume: "/.btrfs-retired".to_string(),
                subvolumes: vec![subvol("data", None)],
                device: "/dev/sdz".to_string(),
                snapshot_dir: ".btrbk-snapshots".to_string(),
                target_subdirs: vec![],
                target_labels: vec!["no-such-target".to_string()],
            },
        ];
        Config {
            targets,
            sources,
            ..Config::default()
        }
    }

    #[test]
    fn render_btrbk_conf_renders_the_whole_file_for_a_multi_target_config() {
        // Asserted in full because every line is load-bearing: the `target`
        // lines decide which drive a subvolume is sent to, the
        // `target_preserve` lines decide how long it is kept there, and
        // `snapshot_name` is the on-disk identity of each send/receive chain.
        let expected = concat!(
            "# Generated by btrdasd setup — do not edit.\n",
            "# Modify /etc/das-backup/config.toml and run: sudo btrdasd setup --upgrade\n",
            "\n",
            "# Global settings\n",
            "transaction_log         /var/log/btrbk.log\n",
            "stream_buffer           256m\n",
            "stream_compress         zstd\n",
            "lockfile                /var/lock/btrbk.lock\n",
            "\n",
            "# Source snapshots — minimal, for send reference\n",
            "snapshot_preserve_min   latest\n",
            "snapshot_preserve       2d\n",
            "\n",
            "# Default target retention (from primary-22tb)\n",
            "target_preserve_min     latest\n",
            "target_preserve         7d 4w 12m 1y\n",
            "\n",
            // target_labels = [] fans out to every target. The primary
            // inherits the global retention; each recovery drive carries its
            // own shorter one as an override.
            "# nvme\n",
            "volume /.btrfs-nvme\n",
            "  snapshot_dir          .btrbk-snapshots\n",
            "  target                /mnt/backup-22tb/nvme\n",
            "  target                /mnt/backup-system-recovery-A/nvme\n",
            "    target_preserve     7d\n",
            "  target                /mnt/backup-system-recovery-B/nvme\n",
            "    target_preserve     7d\n",
            "\n",
            // `@` and `@root` both strip to `root`; btrbk refuses two
            // subvolumes that would write the same snapshot, so both are
            // renamed. `forget::parse_subvol_snapshot_names` and
            // `backup-run.sh` rely on exactly these two names.
            "  subvolume             @\n",
            "    snapshot_name       root-\n",
            "\n",
            "  subvolume             @home\n",
            "    snapshot_name       home\n",
            "\n",
            "  subvolume             @root\n",
            "    snapshot_name       root-root\n",
            "\n",
            "  subvolume             @var/log\n",
            "    snapshot_name       var-log\n",
            "\n",
            // Scoped to the primary: bulk data must never reach the 2 TB
            // recovery drives. No target_subdirs, so the label is the subdir.
            "# hdd-projects\n",
            "volume /.btrfs-hdd\n",
            "  snapshot_dir          ClaudeCodeProjects/.btrbk-snapshots\n",
            "  target                /mnt/backup-22tb/hdd-projects\n",
            "\n",
            "  subvolume             ClaudeCodeProjects\n",
            "    snapshot_name       ClaudeCodeProjects\n",
            "\n",
            "  subvolume             ClaudeCodeProjects/DAS-Backup-Manager\n",
            "    snapshot_name       das-backup-manager\n",
            "\n",
            // "retired" names a target that is not configured, so it gets no
            // volume block at all: a block without a target line would make
            // btrbk snapshot the source and send it nowhere.
        );
        assert_eq!(render_btrbk_conf(&multi_target_config()), expected);
    }

    #[test]
    fn render_btrbk_conf_overrides_retention_only_where_it_differs_from_the_primary() {
        // A mirror with the primary's own retention inherits the global
        // `target_preserve`; repeating it per target would be noise that
        // hides the overrides which do matter.
        let mut config = multi_target_config();
        config.targets[1].retention = config.targets[0].retention.clone();
        let result = render_btrbk_conf(&config);
        assert!(
            result.contains(concat!(
                "  target                /mnt/backup-22tb/nvme\n",
                "  target                /mnt/backup-system-recovery-A/nvme\n",
                "  target                /mnt/backup-system-recovery-B/nvme\n",
                "    target_preserve     7d\n",
                "\n",
            )),
            "{result}"
        );
        assert_eq!(result.matches("    target_preserve     ").count(), 1);
    }

    #[test]
    fn render_btrbk_conf_scopes_a_source_to_a_mirror_alone() {
        // target_labels selects by label, whatever the target's role.
        let mut config = multi_target_config();
        config.sources[0].target_labels = vec!["system-recovery-B-2tb".to_string()];
        let result = render_btrbk_conf(&config);
        assert!(
            result.contains(concat!(
                "volume /.btrfs-nvme\n",
                "  snapshot_dir          .btrbk-snapshots\n",
                "  target                /mnt/backup-system-recovery-B/nvme\n",
                "    target_preserve     7d\n",
                "\n",
            )),
            "{result}"
        );
        assert!(!result.contains("/mnt/backup-22tb/nvme"), "{result}");
        assert!(
            !result.contains("/mnt/backup-system-recovery-A/nvme"),
            "{result}"
        );
    }

    #[test]
    fn format_retention_emits_only_the_non_zero_periods() {
        // A period the config leaves at zero is omitted, in the fixed order
        // daily, weekly, monthly, yearly; 1 is the smallest count that must
        // be rendered. This string is each target's whole retention policy.
        let cases = [
            (retention(7, 4, 12, 1), "7d 4w 12m 1y"),
            (retention(1, 1, 1, 1), "1d 1w 1m 1y"),
            (retention(7, 0, 0, 0), "7d"),
            (retention(0, 4, 0, 0), "4w"),
            (retention(0, 0, 12, 0), "12m"),
            (retention(0, 0, 0, 1), "1y"),
            (retention(1, 0, 0, 0), "1d"),
            (retention(0, 1, 0, 0), "1w"),
            (retention(0, 0, 1, 0), "1m"),
            (retention(0, 4, 2, 0), "4w 2m"),
            (retention(7, 0, 0, 2), "7d 2y"),
            (retention(0, 4, 12, 4), "4w 12m 4y"),
        ];
        for (retention, expected) in cases {
            assert_eq!(format_retention(&retention), expected, "{retention:?}");
        }
    }

    #[test]
    fn format_retention_falls_back_to_four_weeks_when_every_period_is_zero() {
        // An all-zero retention must not leave `target_preserve` without an
        // argument, nor render "0d 0w 0m 0y"; it gets the four-week fallback.
        assert_eq!(format_retention(&retention(0, 0, 0, 0)), "4w");
        assert_eq!(format_retention(&Retention::default()), "4w");
    }

    fn snapshot_names(subvols: &[(&str, Option<&str>)]) -> Vec<String> {
        let subvols: Vec<SubvolConfig> = subvols
            .iter()
            .map(|(name, snapshot_name)| subvol(name, *snapshot_name))
            .collect();
        resolve_snapshot_names(&subvols)
    }

    #[test]
    fn resolve_snapshot_names_leaves_unique_names_alone() {
        // The name is the identity of an existing send/receive chain:
        // renaming a subvolume that collides with nothing would strand every
        // snapshot already taken of it.
        assert_eq!(
            snapshot_names(&[
                ("@", None),
                ("@home", None),
                ("@var/log", None),
                ("ClaudeCodeProjects", None),
                ("Audiobooks", Some("books")),
            ]),
            ["root", "home", "var-log", "ClaudeCodeProjects", "books"]
        );
    }

    #[test]
    fn resolve_snapshot_names_renames_only_the_colliding_subvolumes() {
        // The production case (bd DAS-Backup-Manager-5ig, -ycr): `@` and
        // `@root` both strip to `root`. Their neighbours keep their names.
        assert_eq!(
            snapshot_names(&[
                ("@", None),
                ("@home", None),
                ("@root", None),
                ("@opt", None)
            ]),
            ["root-", "home", "root-root", "opt"]
        );
    }

    #[test]
    fn resolve_snapshot_names_never_rewrites_an_explicit_name() {
        // An explicit snapshot_name is the operator's decision. When it
        // collides with an algorithmic name, the algorithmic one moves.
        assert_eq!(
            snapshot_names(&[("@home", None), ("users", Some("home"))]),
            ["root-home", "home"]
        );
        assert_eq!(
            snapshot_names(&[("users", Some("home")), ("@home", None), ("@opt", None)]),
            ["home", "root-home", "opt"]
        );
    }

    #[test]
    fn render_systemd_service_full_unit_test() {
        let config = test_config();
        assert_eq!(
            render_systemd_service(&config, true),
            concat!(
                "# Generated by btrdasd setup — do not edit.\n",
                "# Modify /etc/das-backup/config.toml and run: sudo btrdasd setup --upgrade\n",
                "\n",
                "[Unit]\n",
                "Description=DAS Backup - Full BTRFS backup\n",
                "After=local-fs.target\n",
                "\n",
                "[Service]\n",
                "Type=oneshot\n",
                "ExecStart=/usr/local/lib/das-backup/backup-run.sh --full\n",
                "StandardOutput=journal\n",
                "StandardError=journal\n",
                "Nice=19\n",
                "IOSchedulingClass=idle\n",
                "TimeoutStartSec=infinity\n",
                "\n",
                "[Install]\n",
                "WantedBy=multi-user.target\n",
            )
        );
    }

    #[test]
    fn render_systemd_timer_full_puts_the_weekday_ahead_of_the_date() {
        // systemd's OnCalendar grammar is `DayOfWeek Date Time`. "Sun 04:00"
        // from config.toml has to become "Sun *-*-* 04:00:00"; the weekday
        // anywhere else is rejected by systemd and the weekly full backup
        // never fires.
        let config = test_config();
        assert_eq!(config.schedule.full, "Sun 04:00");
        assert_eq!(
            render_systemd_timer(&config, true),
            concat!(
                "# Generated by btrdasd setup — do not edit.\n",
                "# Modify /etc/das-backup/config.toml and run: sudo btrdasd setup --upgrade\n",
                "\n",
                "[Unit]\n",
                "Description=DAS Backup Timer - Weekly full backup\n",
                "\n",
                "[Timer]\n",
                "OnCalendar=Sun *-*-* 04:00:00\n",
                "RandomizedDelaySec=1800\n",
                "Persistent=true\n",
                "WakeSystem=false\n",
                "\n",
                "[Install]\n",
                "WantedBy=timers.target\n",
            )
        );
    }

    #[test]
    fn render_systemd_timer_full_without_a_weekday_fires_daily_at_that_time() {
        let mut config = test_config();
        config.schedule.full = "04:30".to_string();
        let result = render_systemd_timer(&config, true);
        assert!(result.contains("\nOnCalendar=*-*-* 04:30:00\n"), "{result}");
    }

    #[test]
    fn render_systemd_service_test() {
        let config = test_config();
        let result = render_systemd_service(&config, false);
        assert!(result.contains("ExecStart=/usr/local/lib/das-backup/backup-run.sh"));
        assert!(!result.contains("/hddRaid1/"));
        assert!(result.contains("# Generated by btrdasd setup"));
    }

    #[test]
    fn render_systemd_service_timeout_is_unbounded_test() {
        // bd DAS-Backup-Manager-b6f: a backup can defer for hours behind a
        // running scrub pass via the shared maintenance lock, so the unit
        // must never be killed by a finite TimeoutStartSec.
        let config = test_config();
        let incremental = render_systemd_service(&config, false);
        let full = render_systemd_service(&config, true);
        assert!(incremental.contains("TimeoutStartSec=infinity"));
        assert!(full.contains("TimeoutStartSec=infinity"));
        assert!(!incremental.contains("TimeoutStartSec=21600"));
        assert!(!full.contains("TimeoutStartSec=21600"));
    }

    #[test]
    fn render_systemd_timer_test() {
        let config = test_config();
        let result = render_systemd_timer(&config, false);
        assert!(result.contains("OnCalendar=*-*-* 03:00:00"));
        assert!(result.contains("RandomizedDelaySec=1800"));
    }

    #[test]
    fn render_systemd_scrub_service_test() {
        let config = test_config();
        let result = render_systemd_scrub_service(&config);
        assert!(result.contains("Type=oneshot"));
        assert!(result.contains("ExecStart=/usr/local/bin/btrdasd scrub run"));
        assert!(result.contains("TimeoutStartSec=infinity"));
        assert!(result.contains("# Generated by btrdasd setup"));
        // bd DAS-Backup-Manager-18p: the unit documents its own exit-code
        // split so a reader of `systemctl cat das-scrub.service` sees why
        // findings don't fail the unit, without needing to go read the
        // engine source.
        assert!(result.contains("# Exit semantics"));
        assert!(result.contains("bd DAS-Backup-Manager-18p"));
        // Explicitly scrapped by user decision 2026-07-27 — deferral via the
        // maintenance lock replaces unit-layer cancellation.
        assert!(!result.contains("Conflicts="));
        assert!(!result.contains("RuntimeMaxSec="));
        assert!(!result.contains("ExecStopPost"));
    }

    #[test]
    fn render_systemd_scrub_timer_test() {
        let config = test_config();
        let result = render_systemd_scrub_timer(&config);
        assert!(result.contains("OnCalendar=*-*-01 03:05:00"));
        assert!(result.contains("Persistent=true"));
        // 03:05 deliberately trails the 03:00 backup so the maintenance lock
        // serializes scrub-after-backup; the lock, not randomized timing, is
        // the mechanism.
        assert!(!result.contains("RandomizedDelaySec"));
    }

    #[test]
    fn render_systemd_scrub_timer_uses_configured_calendar_test() {
        let mut config = test_config();
        config.scrub.on_calendar = "*-*-15 02:00:00".to_string();
        let result = render_systemd_scrub_timer(&config);
        assert!(result.contains("OnCalendar=*-*-15 02:00:00"));
    }

    #[test]
    fn render_systemd_doctor_service_test() {
        let config = test_config();
        let result = render_systemd_doctor_service(&config);
        assert!(result.contains("Type=oneshot"));
        assert!(result.contains("ExecStart=/usr/local/bin/btrdasd doctor --check-drift --email"));
        assert!(result.contains("# Generated by btrdasd setup"));
        // bd DAS-Backup-Manager-01u: the unit documents its own exit-code
        // split, mirroring das-scrub.service's precedent.
        assert!(result.contains("# Exit semantics"));
        assert!(result.contains("bd DAS-Backup-Manager-01u"));
        // Deliberately finite (unlike das-backup/das-scrub's infinity) — the
        // doctor's own lock acquisition is non-blocking, so it never has a
        // legitimate reason to run long.
        assert!(result.contains("TimeoutStartSec=600"));
        assert!(!result.contains("TimeoutStartSec=infinity"));
    }

    #[test]
    fn render_systemd_doctor_timer_test() {
        let config = test_config();
        let result = render_systemd_doctor_timer(&config);
        assert!(result.contains("OnCalendar=Sun *-*-* 02:00:00"));
        assert!(result.contains("Persistent=true"));
        // Fixed Sunday 02:00, ahead of the Sunday full backup (04:00) and
        // monthly scrub (05:30 on the 1st) — no RandomizedDelaySec.
        assert!(!result.contains("RandomizedDelaySec"));
    }

    #[test]
    fn render_cron_entry_test() {
        let config = test_config();
        let result = render_cron_entry(&config).expect("valid schedule renders");
        assert!(result.contains("0 3 * * *"));
        assert!(result.contains("/usr/local/lib/das-backup/backup-run.sh"));
    }

    // Counter-tests for bd DAS-Backup-Manager-06p. Each of these produced a
    // silently-defaulted cron entry before the parsers returned Result:
    // "3 AM" became 03:00, and "Friday 04:00" became SUNDAY 04:00.
    #[test]
    fn render_cron_entry_refuses_an_unparsable_time() {
        let mut config = test_config();
        config.schedule.incremental = "3 AM".into();
        let err = render_cron_entry(&config).expect_err("must not silently default to 03:00");
        assert!(err.contains("3 AM"), "{err}");
    }

    #[test]
    fn render_cron_entry_refuses_a_full_weekday_name() {
        let mut config = test_config();
        config.schedule.full = "Friday 04:00".into();
        let err = render_cron_entry(&config).expect_err("must not silently default to Sunday");
        assert!(err.contains("friday"), "{err}");
    }

    #[test]
    fn schedule_errors_are_surfaced_by_config_validate() {
        let mut config = test_config();
        config.schedule.incremental = "0300".into();
        config.schedule.full = "Funday 04:00".into();
        let errors = config.validate();
        assert!(
            errors.iter().any(|e| e.contains("schedule.incremental")),
            "{errors:?}"
        );
        assert!(
            errors.iter().any(|e| e.contains("schedule.full")),
            "{errors:?}"
        );
    }

    #[test]
    fn generated_files_include_embedded_scripts() {
        let config = test_config();
        let generated = GeneratedFiles::generate(&config);
        let manifest = generated.manifest_content();
        assert!(
            manifest.contains("/usr/local/lib/das-backup/backup-run.sh"),
            "missing embedded backup-run.sh at flat path"
        );
        assert!(
            manifest.contains("/usr/local/lib/das-backup/backup-verify.sh"),
            "missing embedded backup-verify.sh at flat path"
        );
        assert!(
            manifest.contains("/usr/local/lib/das-backup/boot-archive-cleanup.sh"),
            "missing embedded boot-archive-cleanup.sh at flat path"
        );
        assert!(
            !manifest.contains("das-backup/scripts/"),
            "scripts/ subdir layout must not reappear — flat layout is canonical"
        );
    }

    #[test]
    fn generated_files_manifest() {
        let config = test_config();
        let generated = GeneratedFiles::generate(&config);
        let manifest = generated.manifest_content();
        assert!(manifest.contains("/etc/btrbk/btrbk.conf"));
        assert!(manifest.contains("backup-run.sh"));
        assert!(manifest.contains("das-backup.service"));
        assert!(manifest.contains("das-backup.timer"));
        assert!(manifest.contains("das-scrub.service"));
        assert!(manifest.contains("das-scrub.timer"));
        assert!(manifest.contains("das-backup-doctor.service"));
        assert!(manifest.contains("das-backup-doctor.timer"));
        assert!(manifest.contains(UDEV_UDISKS_IGNORE_RULES));
    }

    /// `test_config()` plus a RAID-1 target that carries a `mount_uuid`.
    fn config_with_uuid_target() -> Config {
        let mut config = test_config();
        config.targets.push(Target {
            label: "pair".to_string(),
            serial: "ZXA1NYGZ".to_string(),
            serials: vec!["ZXA1NYGZ".to_string(), "ZXA1R71M".to_string()],
            mount_uuid: Some("b2dbe07d-40b9-422e-8ccf-ef4931c40457".to_string()),
            mount: "/mnt/pair".to_string(),
            role: TargetRole::Primary,
            retention: Retention {
                weekly: 0,
                monthly: 0,
                daily: 7,
                yearly: 0,
            },
            display_name: String::new(),
        });
        config
    }

    #[test]
    fn render_udev_udisks_ignore_keys_every_target_serial_and_uuid() {
        // bd DAS-Backup-Manager-xqo: one line per configured serial (scoped to
        // the btrfs partition, so a recovery drive's own ESP is not matched),
        // plus one per configured filesystem UUID.
        let result = render_udev_udisks_ignore(&config_with_uuid_target());
        assert!(result.contains("# Generated by btrdasd setup"));
        for serial in ["ZXA0LMAE", "ZXA1NYGZ", "ZXA1R71M"] {
            let line = format!(
                "SUBSYSTEM==\"block\", ENV{{ID_SERIAL_SHORT}}==\"{serial}\", \
                 ENV{{ID_FS_TYPE}}==\"btrfs\", ENV{{UDISKS_IGNORE}}=\"1\"\n"
            );
            assert!(
                result.contains(&line),
                "missing serial rule for {serial}:\n{result}"
            );
        }
        assert!(result.contains(
            "SUBSYSTEM==\"block\", ENV{ID_FS_UUID}==\"b2dbe07d-40b9-422e-8ccf-ef4931c40457\", \
             ENV{UDISKS_IGNORE}=\"1\"\n"
        ));
        // Three serials + one UUID: exactly four rules, nothing invented for
        // the target that has no mount_uuid.
        assert_eq!(result.matches("ENV{UDISKS_IGNORE}=\"1\"").count(), 4);
    }

    #[test]
    fn render_udev_udisks_ignore_refuses_values_that_would_break_rule_syntax() {
        // A serial or UUID is interpolated into a udev match string. One
        // containing a quote would end the string early and turn the rest of
        // the line into rule syntax, so it gets a comment, never a rule.
        let mut config = test_config();
        config.targets[0].serials = vec!["BAD\", ENV{X}==\"".to_string()];
        config.targets[0].mount_uuid = Some("not a uuid\"".to_string());
        let result = render_udev_udisks_ignore(&config);
        assert_eq!(result.matches("ENV{UDISKS_IGNORE}=\"1\"").count(), 0);
        assert!(!result.contains("BAD"));
        assert_eq!(result.matches("# SKIPPED").count(), 2);
    }

    #[test]
    fn udev_safe_value_accepts_serials_and_uuids_only() {
        assert!(is_udev_safe_value("ZK208Q77"));
        assert!(is_udev_safe_value("b2dbe07d-40b9-422e-8ccf-ef4931c40457"));
        assert!(is_udev_safe_value("WD-WX12_A.3"));
        assert!(!is_udev_safe_value(""));
        assert!(!is_udev_safe_value("a\"b"));
        assert!(!is_udev_safe_value("a b"));
        assert!(!is_udev_safe_value("a*"));
        assert!(!is_udev_safe_value("a|b"));
    }

    #[test]
    fn generated_files_carry_the_udev_rule_under_every_init_system() {
        // udisks does not care which init system is running.
        for system in [
            InitSystem::Systemd,
            InitSystem::Sysvinit,
            InitSystem::Openrc,
        ] {
            let mut config = test_config();
            config.init.system = system;
            let generated = GeneratedFiles::generate(&config);
            let rule = generated
                .files
                .iter()
                .find(|(p, _)| p == UDEV_UDISKS_IGNORE_RULES)
                .map(|(_, c)| c.as_str());
            assert_eq!(rule, Some(render_udev_udisks_ignore(&config).as_str()));
        }
    }
}
